"""HSTR parity fixtures generated by executing frozen official SFWMark source."""
from __future__ import annotations

import base64
import json
import os
import sys
import unittest
from pathlib import Path

import numpy as np
import torch

_TESTS_DIR = Path(__file__).resolve().parent
_PKG_ROOT = _TESTS_DIR.parent
for _path in (str(_PKG_ROOT), str(_TESTS_DIR), str(_PKG_ROOT / "tools")):
    if _path not in sys.path:
        sys.path.insert(0, _path)

import official_sfwmark_source as official_src
from generate_hstr_official_fixtures import REQUIRED_KEYS, base_latents, build_fixtures
from utils.wm import sfw_bundle
from utils.wm.hstr_provider import (
    HSTR_SCORE_DEFINITION,
    HSTR_SCORE_DIRECTION,
    HSTRProvider,
    OFFICIAL_BASE_KEY_SEED,
    OFFICIAL_HSTR_PROFILE,
)

FIXTURE_PATH = _TESTS_DIR / "fixtures" / "hstr_official_fixtures.json"
LATENT_SHAPE = (1, 4, 64, 64)


def load_fixtures() -> dict:
    return json.loads(FIXTURE_PATH.read_text(encoding="utf-8"))


def unpack_tensor(payload: dict) -> torch.Tensor:
    dtype_map = {
        "torch.float32": np.float32,
        "torch.complex64": np.complex64,
        "torch.bool": np.bool_,
    }
    array = np.frombuffer(base64.b64decode(payload["data_b64"]), dtype=dtype_map[payload["dtype"]])
    return torch.from_numpy(array.copy()).reshape(tuple(payload["shape"]))


def provider(key_index: int) -> HSTRProvider:
    return HSTRProvider(
        latent_shape=LATENT_SHAPE,
        device=torch.device("cpu"),
        hstr_profile=OFFICIAL_HSTR_PROFILE,
        hstr_key_index=key_index,
        hstr_rng_device="cpu",
        modelid_target="stabilityai/stable-diffusion-2-1-base",
        scheduler_target="DDIM",
        resolution=512,
    )


class TestHstrOfficialFixtureProvenance(unittest.TestCase):
    def setUp(self):
        self.fixtures = load_fixtures()

    def test_schema_and_commit_are_pinned(self):
        self.assertEqual(self.fixtures["schema"], "hstr_official_fixtures_v1")
        provenance = self.fixtures["provenance"]
        self.assertEqual(provenance["official_commit"], official_src.OFFICIAL_SFWMARK_COMMIT)
        self.assertEqual(provenance["official_utils_sha256"], official_src.OFFICIAL_UTILS_SHA256)
        self.assertIn("executed", self.fixtures["derivation"])

    def test_required_keys_are_present(self):
        self.assertEqual(sorted(int(k) for k in self.fixtures["keys"]), sorted(REQUIRED_KEYS))

    def test_official_constants_match_provider_contract(self):
        constants = self.fixtures["official_constants"]
        self.assertEqual(constants["base_key_seed"], OFFICIAL_BASE_KEY_SEED)
        self.assertEqual(constants["center_slice"], [10, 54])
        self.assertEqual(constants["radius"], 14)
        self.assertEqual(constants["radius_cutoff"], 3)
        self.assertEqual(constants["watermark_channels"], [3])
        self.assertEqual(constants["heterogeneous_channels"], [0])
        self.assertEqual(constants["score_definition"], HSTR_SCORE_DEFINITION)
        self.assertEqual(constants["score_direction"], HSTR_SCORE_DIRECTION)

    def test_no_stubbed_dependency_influenced_hstr_calls(self):
        self.assertEqual(self.fixtures["stub_usage_during_hstr_calls"], [])


class TestHstrCommittedOfficialFixtures(unittest.TestCase):
    """Provider vs official-source fixtures, element by element, zero tolerance."""

    def setUp(self):
        self.fixtures = load_fixtures()
        self.base_latents = unpack_tensor(self.fixtures["base_latents"])

    def test_base_latent_fixture_is_reproducible(self):
        self.assertTrue(torch.equal(self.base_latents, base_latents()))
        self.assertEqual(sfw_bundle.sha256_tensor(self.base_latents), self.fixtures["base_latents"]["sha256"])

    def test_selected_patterns_match_every_element(self):
        for key_index in REQUIRED_KEYS:
            with self.subTest(key=key_index):
                entry = self.fixtures["keys"][str(key_index)]
                expected = unpack_tensor(entry["selected_pattern"])
                actual = provider(key_index).gt_patch.cpu()
                self.assertEqual(entry["key_seed"], OFFICIAL_BASE_KEY_SEED + key_index)
                self.assertEqual(tuple(actual.shape), tuple(entry["selected_pattern"]["shape"]))
                self.assertTrue(torch.equal(actual, expected))
                self.assertEqual(sfw_bundle.sha256_tensor(actual), entry["selected_pattern"]["sha256"])

    def test_injected_latents_match_every_element(self):
        for key_index in REQUIRED_KEYS:
            with self.subTest(key=key_index):
                entry = self.fixtures["keys"][str(key_index)]
                expected = unpack_tensor(entry["injected_latent"])
                actual = provider(key_index).get_wm_latents(latents_clean=self.base_latents.clone())["zT_torch"].cpu()
                self.assertTrue(torch.equal(actual, expected))
                self.assertEqual(sfw_bundle.sha256_tensor(actual), entry["injected_latent"]["sha256"])

    def test_distances_and_scores_match_exactly(self):
        for key_index in REQUIRED_KEYS:
            with self.subTest(key=key_index):
                entry = self.fixtures["keys"][str(key_index)]
                injected = unpack_tensor(entry["injected_latent"])
                scores = provider(key_index).get_accuracies(injected)
                self.assertEqual(scores["hstr_channel_min_l1"], entry["per_item_raw_distance"])
                self.assertEqual(scores["hstr_score"], entry["canonical_score"])
                self.assertEqual(scores["score_definition"], HSTR_SCORE_DEFINITION)

    def test_identification_result_selects_the_true_key(self):
        for key_index in REQUIRED_KEYS:
            with self.subTest(key=key_index):
                result = self.fixtures["keys"][str(key_index)]["key_identification_result"]
                self.assertEqual(int(result["identified_key_index"]), key_index)
                true_distance = result["candidate_raw_distances"][str(key_index)]
                self.assertEqual(true_distance, min(result["candidate_raw_distances"].values()))


@unittest.skipUnless(
    official_src.official_available(),
    f"frozen official SFWMark source unavailable; set ${official_src.OFFICIAL_SRC_ENV}",
)
class TestHstrLiveOfficialSource(unittest.TestCase):
    def test_committed_fixture_regenerates_from_official_source(self):
        regenerated = sfw_bundle.canonical_json(build_fixtures())
        committed = sfw_bundle.canonical_json(load_fixtures())
        self.assertEqual(regenerated, committed)


if __name__ == "__main__":
    unittest.main()
